using System;using System.IO;using System.Text;using System.Linq;using System.Diagnostics;using System.Globalization;using Frociart;
internal static class PostTestPlanPerformanceTests {
 static int Main(string[] args){try{var source=new StringBuilder("x=0\n");for(int i=0;i<220;i++)source.Append("RIPETI\nx=x+1\nFINCHE x>0\n");source.Append("STAMPA x");var program=FlowSource.Compile(FlowPseudocode.Decode(source.ToString()));if(!program.CanGenerate)throw new Exception("Performance fixture invalid");var scope=program.Scopes[0];for(int i=0;i<3;i++)if(!FlowSourcePlan.Create(scope).Structured)throw new Exception("Large repeat sequence lost its structure");double[] samples=new double[15];for(int i=0;i<samples.Length;i++){var clock=Stopwatch.StartNew();var plan=FlowSourcePlan.Create(scope);clock.Stop();if(!plan.Structured)throw new Exception("Plan lost structure");samples[i]=clock.Elapsed.TotalMilliseconds;}var sorted=samples.OrderBy(x=>x).ToArray();File.WriteAllText(Path.Combine(args[0],"planner-performance.json"),"{\"status\":\"MEASURED\",\"blocks\":"+scope.Blocks.Count+",\"repeatLoops\":220,\"samples_ms\":["+String.Join(",",samples.Select(x=>x.ToString("R",CultureInfo.InvariantCulture)))+"],\"median_ms\":"+sorted[7].ToString("R",CultureInfo.InvariantCulture)+",\"max_ms\":"+sorted[14].ToString("R",CultureInfo.InvariantCulture)+",\"scope\":\"Control-flow planner only on this Windows host; not total UI latency or Android/device performance\"}");Console.WriteLine("POST_TEST_PLAN_PERFORMANCE MEASURED blocks="+scope.Blocks.Count+" median_ms="+sorted[7].ToString("F3",CultureInfo.InvariantCulture)+" max_ms="+sorted[14].ToString("F3",CultureInfo.InvariantCulture));return 0;}catch(Exception error){Console.WriteLine(error);return 1;}}
}
